def clamp_negative_spark_balances(apps, schema_editor):
    """
    Make the new non-negative checks safe to add.

    ``PositiveBigIntegerField`` already emits an unnamed ``>= 0`` check on
    PostgreSQL, so a healthy database has nothing to fix. This runs anyway
    because ``AddConstraint`` validates existing rows and would abort the whole
    deploy on a database restored from a dump that lost those checks. Clamping
    to zero is the conservative direction: it can only ever remove Sparks that
    should not have existed.
    """
    for model_name, column in (("SparkPool", "spark_pools"), ("GuestTokenQuota", "guest_token_quotas")):
        model = apps.get_model("capp", model_name)
        repaired = model.objects.filter(sparks__lt=0).update(sparks=0)
        if repaired:
            print(f"  Clamped {repaired} negative spark balance(s) in {column}")


